import{_ as i,o as s,c as a,a6 as t}from"./chunks/framework.B_q3ZJNF.js";const k=JSON.parse('{"title":"JS 没有 GUI：运行时是被嵌入的","description":"","frontmatter":{"title":"JS 没有 GUI：运行时是被嵌入的"},"headers":[],"relativePath":"js-gui-course/03-embedded-runtime.md","filePath":"js-gui-course/docs/03-embedded-runtime.md"}'),n={name:"js-gui-course/03-embedded-runtime.md"};function o(d,e,l,c,r,p){return s(),a("div",null,[...e[0]||(e[0]=[t(`<h1 id="js-没有-gui-运行时是被嵌入的" tabindex="-1">JS 没有 GUI：运行时是被嵌入的 <a class="header-anchor" href="#js-没有-gui-运行时是被嵌入的" aria-label="Permalink to &quot;JS 没有 GUI：运行时是被嵌入的&quot;">​</a></h1><p>一个每个 JS 开发者都撞过的报错：同一段代码，浏览器里跑得好好的，搬进 Node 脚本立刻 <code>ReferenceError: window is not defined</code>；写 Electron 时更迷惑——主进程文件里 <code>window</code> 没有、<code>document</code> 没有，渲染进程里却都有，还能多出一套 <code>ipcRenderer</code>。很多人把这当成「环境不同，背下来就好」。但只要追问一句「JS 语言规范里哪一章定义了 window」，整个幻觉就塌了：<strong>没有任何一章。<code>window</code>、<code>document</code>、<code>process</code>、<code>ipcRenderer</code> 全都不是 JS 的东西，它们是宿主（host）塞进来的</strong>。这一章讲清塞的动作是怎么发生的，因为下一章我们要亲手当一回宿主。</p><h2 id="引擎只是一台可租赁的机器" tabindex="-1">引擎只是一台可租赁的机器 <a class="header-anchor" href="#引擎只是一台可租赁的机器" aria-label="Permalink to &quot;引擎只是一台可租赁的机器&quot;">​</a></h2><p>把「JS 运行时」拆开看，里面是分层的。最底下是引擎（V8、JavaScriptCore、QuickJS……），它只认识 ECMAScript 规范：语法、类型、函数、原型链、Promise，外加一个空的执行环境。引擎是个库（C++ 写的库），它自己不会出现在进程列表里，也不认识屏幕、文件、网卡。规范层面它唯一知道的「外部世界」是一个叫全局对象的槽位——引擎启动时它是空的。</p><p>谁来填这个槽位？宿主。宿主是一个原生程序（浏览器、Node、Electron 的某个进程），它做三件事：</p><ol><li>把引擎当库链接进自己，创建隔离的执行环境（V8 里叫 isolate + context——「隔离」意味着里面的全局对象互不可见，一个页面污染不了另一个页面）；</li><li>把自己的能力包装成函数和对象，逐个挂到全局上（浏览器挂 <code>document</code>/<code>window</code>，Node 挂 <code>process</code>/<code>require</code>，Electron 渲染进程挂网页 API 加 <code>ipcRenderer</code>）；</li><li>提供执行驱动：什么时候跑你的脚本、事件循环归谁管（Node 的循环在 libuv 里，浏览器的循环嵌在标签页的渲染管线里）。</li></ol><p>这叫嵌入（embedding）。所以「JS 能做 GUI」是个错觉——JS 从头到尾没获得过 GUI 能力，是某个宿主恰好有 GUI 能力、又恰好愿意把它包装成 JS 函数挂出来。<strong>引擎提供计算，宿主提供世界</strong>。</p><h2 id="同一个引擎-三个世界" tabindex="-1">同一个引擎，三个世界 <a class="header-anchor" href="#同一个引擎-三个世界" aria-label="Permalink to &quot;同一个引擎，三个世界&quot;">​</a></h2><p>用这个分层回看开头的报错，一切就对齐了：</p><ul><li>浏览器：宿主是浏览器进程，挂上 <code>window</code>（框选、弹窗）、<code>document</code>（DOM）、<code>fetch</code>（网络栈）。JS 之所以「能画画」，是因为宿主把渲染管线的一部分以 DOM API 的形式租给了它。</li><li>Node：宿主是 Node 可执行文件，它压根没有 GUI，自然什么都不挂，只挂 <code>process</code>、<code>fs</code>、<code>require</code>。<code>window is not defined</code> 不是出错，是宿主诚实地告诉你「我这里没有这玩意」。</li><li>Electron 主进程/渲染进程：这是最有趣的一个——同一个 App 里有两个宿主角色。主进程的宿主是「Node + 窗口/系统能力」，渲染进程的宿主是「Chromium 网页环境 + 一小撮桥接口」。同一份 V8，两个世界注入的全局完全不同。为什么拆成两个进程、两边怎么通信，是第 7、8 章的正题；本章只需要确认：<strong>判断「这段 JS 里有什么可用」，看的从来不是 JS 版本，而是宿主是谁</strong>。</li></ul><p>还有一个常见误区顺便拆掉：「<code>setTimeout</code> 是 JS 的函数吗？」不是。引擎只保证 Promise 的语义；<code>setTimeout</code>、<code>setInterval</code>、<code>requestAnimationFrame</code> 都是宿主挂出来的，计时由宿主实现。这也解释了为什么不同宿主的 <code>setTimeout</code> 最小间隔、精度各不相同——同一台租赁机器，房东给的配件不一样。</p><h2 id="宿主注入的最小示意" tabindex="-1">宿主注入的最小示意 <a class="header-anchor" href="#宿主注入的最小示意" aria-label="Permalink to &quot;宿主注入的最小示意&quot;">​</a></h2><p>下一章的实验场要写的 <code>createRuntime</code>，骨架用十行伪码就能说清：</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 原理示意：宿主如何造出一个「JS 世界」</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> runtime</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> createRuntime</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;main&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)      </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 相当于创建 isolate + context</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">runtime.globals.createWindow </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> wrap</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(创建窗口的原生实现)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">runtime.globals.setTitle    </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> wrap</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(改标题的原生实现)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">runtime.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">run</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(() </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {                        </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 把你的 JS 脚本放进这个世界执行</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  // 脚本眼里：createWindow 是「天生就有的」</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">})</span></span></code></pre></div><p>注意两个要点。其一，<code>globals</code> 是宿主单方面填的字典：宿主挂什么，JS 就有什么，反过来 JS 在自己全局上乱挂的东西，宿主完全不知情——边界是单向透明的。其二，<code>wrap</code> 不是直接赋值：原生函数与 JS 函数的参数、返回值要跨语言边界，需要一层转换——这层转换就是下一章的主角绑定层（binding），<code>window.alert</code> 能跑，是因为有人替它把字符串从 JS 字符串翻译成了原生字符串。</p><p>宿主与第 2 章的关系也在此接上了：宿主提供世界，而原生世界的 heartbeat 是消息循环——宿主注入的很多「同步函数」，内里其实往某个队列里塞了消息。等第 9 章事件回流时你会看到这条环闭合的样子。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>引擎是一台不认识世界的计算机，宿主负责把它搬进自己的世界、再把世界的能力挂到它的全局上。<code>window</code> 与 <code>process</code> 的差异、Electron 两个进程 API 面的差异，全是宿主注入清单的差异。理解了「注入」这个动作，你就再也不会问「JS 怎么获得 GUI 能力」——它从来没获得过，它只是被放进了一个恰好有 GUI 的程序里，并且拿到了那个程序的遥控器。下一章我们把遥控器的电路板拆开：binding 层——JS 函数调用怎么穿过语言边界、进入原生代码，参数怎么序列化、返回值怎么回来。</p>`,18)])])}const u=i(n,[["render",o]]);export{k as __pageData,u as default};
